import { mkdir, rm, writeFile } from "node:fs/promises";
import path from "node:path";
import { DeleteObjectCommand, PutObjectCommand, S3Client } from "@aws-sdk/client-s3";

/** Where uploaded files live. Keys are generated by the app, never taken from user input. */
export interface ObjectStorage {
  put(key: string, body: Buffer, contentType: string): Promise<void>;
  delete(key: string): Promise<void>;
  publicUrl(key: string): string;
  /** Inverse of `publicUrl`; null for URLs this storage didn't produce. */
  keyFromUrl(url: string): string | null;
}

const KEY = /^[a-z0-9][a-z0-9/_.-]{0,250}$/;

function urlHelpers(publicBaseUrl: string) {
  const base = publicBaseUrl.replace(/\/+$/, "");
  return {
    publicUrl: (key: string) => `${base}/${key}`,
    keyFromUrl: (url: string) => (url.startsWith(`${base}/`) ? url.slice(base.length + 1) : null),
  };
}

function assertKey(key: string): void {
  if (!KEY.test(key) || key.includes("..")) throw new Error(`Invalid storage key: ${key}`);
}

/** Development/test storage on the local disk, served by the API under /uploads. */
export function createLocalStorage(rootDir: string, publicBaseUrl: string): ObjectStorage & { rootDir: string } {
  const root = path.resolve(rootDir);
  const resolve = (key: string) => {
    assertKey(key);
    const full = path.resolve(root, key);
    if (!full.startsWith(root + path.sep)) throw new Error("Key escapes storage root");
    return full;
  };
  return {
    rootDir: root,
    ...urlHelpers(publicBaseUrl),
    async put(key, body) {
      const file = resolve(key);
      await mkdir(path.dirname(file), { recursive: true });
      await writeFile(file, body);
    },
    async delete(key) {
      await rm(resolve(key), { force: true });
    },
  };
}

export type S3Settings = {
  bucket: string;
  region: string;
  endpoint?: string;
  accessKeyId: string;
  secretAccessKey: string;
  forcePathStyle: boolean;
  publicBaseUrl: string;
};

/** S3-compatible object storage: AWS S3, Cloudflare R2, MinIO, DigitalOcean Spaces… */
export function createS3Storage(settings: S3Settings): ObjectStorage {
  const client = new S3Client({
    region: settings.region,
    endpoint: settings.endpoint,
    forcePathStyle: settings.forcePathStyle,
    credentials: { accessKeyId: settings.accessKeyId, secretAccessKey: settings.secretAccessKey },
  });
  return {
    ...urlHelpers(settings.publicBaseUrl),
    async put(key, body, contentType) {
      assertKey(key);
      await client.send(
        new PutObjectCommand({
          Bucket: settings.bucket,
          Key: key,
          Body: body,
          ContentType: contentType,
          // Keys are unique per upload, so files never change once written.
          CacheControl: "public, max-age=31536000, immutable",
        }),
      );
    },
    async delete(key) {
      assertKey(key);
      await client.send(new DeleteObjectCommand({ Bucket: settings.bucket, Key: key }));
    },
  };
}
